# Writes Keepy Uppy's hedra command files (every model but the hero ball) and its drawn textures: a
# beach at sunset. Run from models/env: /usr/bin/python3 make_env.py. Hedra is up Z, front -Y (the GLB
# comes out Y up, front +Z: renderer z = -hedra y); colours are exact Journey hexes.
import math
import os
import random

from PIL import Image

HEX = {"sandhi": "ffcf8e", "sand": "f0c297", "sandwet": "cf968c", "sanddk": "8f5765", "sandink": "52294b",
       "deep": "144491", "sea": "488bd4", "sky": "78d7ff", "foam": "b0fff1", "white": "faffff",
       "leafdk": "2c645e", "leaf": "429058", "leafhi": "77b02a", "trunk": "9c341a", "trunkhi": "d4662f",
       "red": "d41e3c", "redhi": "ed4c40", "pink": "ff417d", "pinkhi": "ff7a7d", "magenta": "d61a88",
       "sun": "fff540", "sunlow": "ffcf8e", "glow": "f5a15d", "yellow": "ffb84a", "orange": "ed7b39",
       "plum": "5b537d", "lilac": "928fb8", "rockdk": "392946"}


def rgb(name):
    h = HEX[name]
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def col(name):
    return "--base-color " + " ".join(f"{c / 255:.4f}" for c in rgb(name))


def emit(name):
    c = " ".join(f"{v / 255:.4f}" for v in rgb(name))
    return f"--base-color {c} --emission {c}"


def write(name, lines):
    with open(name + ".txt", "w") as f:
        f.write("\n".join(lines) + "\n")


os.makedirs("textures", exist_ok=True)
rnd = random.Random(9)

# ---------------------------------------------------------------- textures
# sand: 18 x 6.7 m at 0.25 m a texel (72 x 27); dry sand, a wet band at the sea's edge (the top rows:
# hedra +Y, renderer far), ripples of the lighter step, white shells (2 x 1)
im = Image.new("RGB", (72, 27), rgb("sand"))
for x in range(72):
    edge = 3 + int(1.2 * math.sin(x * 0.35) + 0.8 * math.sin(x * 0.13 + 1))
    for y in range(0, max(1, edge)):
        im.putpixel((x, y), rgb("sandwet"))
for _ in range(40):
    x, y, n = rnd.randrange(72), rnd.randrange(6, 27), rnd.choice((2, 3, 4))
    for k in range(n):
        im.putpixel(((x + k) % 72, y), rgb("sandhi"))
for _ in range(10):
    x, y = rnd.randrange(71), rnd.randrange(8, 27)
    im.putpixel((x, y), rgb("white"))
    im.putpixel((x + 1, y), rgb("white"))
im.save("textures/sand.png")
# sea: 18 x 13 m at 0.3 m a texel (60 x 43): deep blue far (top), lighter near, foam dashes, and the
# sun's glitter path down from the sun (x 2.5 m: column 38)
im = Image.new("RGB", (60, 43), rgb("sea"))
for y in range(0, 22):
    for x in range(60):
        im.putpixel((x, y), rgb("deep"))
for _ in range(60):
    x, y, n = rnd.randrange(60), rnd.randrange(43), rnd.choice((2, 3, 3, 4))
    c = rgb("sea") if y < 22 else rgb("sky")
    for k in range(n):
        im.putpixel(((x + k) % 60, y), c)
for y in range(0, 43):
    w = 2 + y // 9
    for k in range(-w, w + 1):
        if rnd.random() < 0.55:
            im.putpixel((38 + k + rnd.randrange(-1, 2), y), rgb("sun") if y < 14 else rgb("yellow"))
im.save("textures/sea.png")
# towel: pink and white stripes, 8 x 4
im = Image.new("RGB", (8, 4))
for x in range(8):
    for y in range(4):
        im.putpixel((x, y), rgb("pink") if (x // 2) % 2 == 0 else rgb("white"))
im.save("textures/towel.png")

# ---------------------------------------------------------------- sand, sea, sun, clouds
write("beach", [
    "# The beach: sand 18 x 6.7 m (renderer z -3.2 .. 3.5), its front face, and the sea 18 x 13 m",
    "# (renderer z -16 .. -3) just under the sand's height, unlit: a sunset sea keeps its painted colours.",
    "# Generated by make_env.py.",
    "new",
    "material new Sand --base-color 1 1 1 --no-slot",
    f"material new SandSide {col('sanddk')} --no-slot",
    "material new Sea --base-color 1 1 1 --emission 1 1 1 --no-slot",
    "add mesh cube --name Sand --size 1 --location 0 -0.15 -0.4",
    "scale 18 6.7 0.8",
    "apply --scale",
    "material assign SandSide",
    "active Sand",
    "mode edit",
    'select face where "normal.z < -0.9 || normal.x > 0.9 || normal.x < -0.9 || normal.y > 0.9"',
    "delete only-faces",
    'select face where "normal.z > 0.9"',
    "material assign Sand",
    "uv project-from-view top --scale-to-bounds",
    "mode object",
    "material texture Sand base-color textures/sand.png",
    "add mesh plane --name Sea --size 1 --location 0 9.5 -0.1",
    "scale 18 13 1",
    "apply --scale",
    "material assign Sea",
    "active Sea",
    "mode edit",
    "select all",
    "uv project-from-view top --scale-to-bounds",
    "mode object",
    "material texture Sea base-color textures/sea.png",
    "select all",
    "shade flat",
    "export beach.glb",
])
S = ["# The setting sun: a 16-sided disc 3.6 m across, standing at the sea's far edge, half under the",
     "# horizon; a ring of the warmer step round it. Unlit. Faces the camera (-Y). Generated by make_env.py.",
     "new",
     f"material new Sun {emit('sun')} --no-slot",
     f"material new Halo {emit('sunlow')} --no-slot",
     "add mesh cylinder --name Halo --vertices 16 --radius 1.9 --depth 0.1 --location 0 0.15 0",
     "material assign Halo",
     "add mesh cylinder --name Sun --vertices 16 --radius 1.5 --depth 0.1 --location 0 0 0",
     "material assign Sun",
     "select Halo Sun",
     "set rotation 90 0 0",
     "apply --rotation"]
S += ["select all", "shade flat", "export sun.glb"]
write("sun", S)
C = ["# Sunset clouds: long flat low-poly slabs in pink, coral and amber, unlit, facing the camera.",
     "new",
     f"material new CloudA {emit('pinkhi')} --no-slot",
     f"material new CloudB {emit('glow')} --no-slot",
     f"material new CloudC {emit('magenta')} --no-slot"]
for i, (x, z, w, h, m) in enumerate(((-5.5, 5.2, 4.0, 0.5, "CloudA"), (-3.2, 4.7, 2.6, 0.4, "CloudC"),
                                      (4.8, 6.1, 4.6, 0.55, "CloudB"), (6.6, 5.5, 2.4, 0.4, "CloudA"),
                                      (0.8, 6.8, 3.0, 0.45, "CloudC"), (-1.0, 3.9, 2.2, 0.32, "CloudB"))):
    C += [f"add mesh cylinder --name Cloud{i} --vertices 6 --radius 1 --depth 0.1 --location 0 0 0",
          f"scale {w / 2} {h / 2} 1", "apply --scale", "set rotation 90 0 0", "apply --rotation",
          f"set location {x} 0 {z}", f"material assign {m}"]
C += ["select all", "shade flat", "export clouds.glb"]
write("clouds", C)

# ---------------------------------------------------------------- the shore's foam (baked loop)
# A wavy strip of foam that washes up the sand and back: 4 s, linear keys, 12 fps when baked.
F = ["# The shore's foam: a wavy strip of flat white lumps along the waterline that washes in and out",
     "# (4 s loop, rigid). Generated by make_env.py.",
     "new",
     "fps 12",
     "frame range 0 48",
     f"material new Foam {col('white')} --no-slot",
     f"material new Lace {col('foam')} --no-slot"]
for i in range(19):
    x = -9 + i * 1.0
    y = 0.15 * math.sin(i * 1.3)
    F += [f"add mesh cube --name F{i} --size 1 --location {x:.2f} {y:.2f} 0.0",
          f"scale {rnd.uniform(0.9, 1.3):.2f} {rnd.uniform(0.25, 0.45):.2f} 0.08", "apply --scale",
          f"material assign {'Foam' if i % 3 else 'Lace'}"]
F += ["select " + " ".join(f"F{i}" for i in range(19)), "active F0", "join", "rename F0 Foam",
      "cursor set 0 0 0", "origin set --to cursor",
      "set location 0 0 0", "keyframe insert --channels loc --frame 0",
      "set location 0 -0.55 0", "keyframe insert --channels loc --frame 24",
      "set location 0 0 0", "keyframe insert --channels loc --frame 48",
      "frame set 0", "select all", "shade flat", "export foam.glb --bake-animations"]
write("foam", F)

# ---------------------------------------------------------------- palm, umbrella, castle, towel, rocks
P = ["# A leaning palm: six trunk segments bending right, eight drooping fronds, three coconuts.",
     "new",
     f"material new Trunk {col('trunk')} --no-slot",
     f"material new Frond {col('leaf')} --no-slot",
     f"material new Nut {col('trunkhi')} --no-slot"]
pts = [(0, 0, 0)]
for i in range(6):
    a = math.radians(4 + i * 4.5)
    px, py, pz = pts[-1]
    pts.append((px + math.sin(a) * 0.95, py, pz + math.cos(a) * 0.95))
for i in range(6):
    (ax, ay, az), (bx, by, bz) = pts[i], pts[i + 1]
    L = math.dist(pts[i], pts[i + 1])
    tilt = math.degrees(math.atan2(bx - ax, bz - az))
    r1 = 0.26 - i * 0.02
    P += [f"add mesh cylinder --name T{i} --vertices 6 --radius {r1:.3f} --depth {L + 0.08:.3f} --location 0 0 0",
          f"set rotation 0 {tilt:.2f} 0", "apply --rotation",
          f"set location {(ax + bx) / 2:.3f} {(ay + by) / 2:.3f} {(az + bz) / 2:.3f}", "material assign Trunk"]
tx, ty, tz = pts[-1]
for k in range(8):
    yaw = k * 45 + 10
    P += [f"add mesh cone --name Fr{k} --vertices 4 --radius1 0.42 --radius2 0.02 --depth 2.4 --location 0 0 0",
          "scale 1 0.2 1", "apply --scale",
          "set rotation 0 105 0", "apply --rotation",           # point out sideways, drooping 15
          f"set rotation 0 0 {yaw}", "apply --rotation",
          f"set location {tx:.3f} {ty:.3f} {tz + 0.05:.3f}", "material assign Frond"]
for k, (dx, dy) in enumerate(((0.2, 0.15), (-0.15, 0.2), (0.05, -0.22))):
    P += [f"add mesh ico-sphere --name N{k} --subdivisions 1 --radius 0.17 --location {tx + dx:.3f} {ty + dy:.3f} {tz - 0.18:.3f}",
          "material assign Nut"]
P += ["select all", "shade flat", "export palm.glb"]
write("palm", P)

U = ["# A beach umbrella: a white pole, an 8-gore canopy (pink and white), tilted. Origin at its foot.",
     "new",
     f"material new Pole {col('white')} --no-slot",
     f"material new Pink {col('pink')} --no-slot",
     f"material new White {col('white')} --no-slot",
     "add mesh cylinder --name Pole --vertices 6 --radius 0.06 --depth 2.6 --location 0 0 1.3",
     "material assign Pole",
     "add mesh cone --name Canopy --vertices 8 --radius1 1.5 --radius2 0.05 --depth 0.7 --location 0 0 2.45",
     "material assign White",
     "active Canopy",
     "mode edit",
     'select face where "pos.y > 0 && abs(pos.x) < 0.42 * pos.y || pos.y < 0 && abs(pos.x) < -0.42 * pos.y"',
     "material assign Pink",
     'select face where "pos.x > 0 && abs(pos.y) < 0.42 * pos.x || pos.x < 0 && abs(pos.y) < -0.42 * pos.x"',
     "material assign Pink",
     'select face where "normal.z < -0.9"',
     "delete only-faces",
     "mode object",
     "select all",
     "set rotation 0 -12 0",
     "apply --rotation",
     "shade flat",
     "export umbrella.glb"]
write("umbrella", U)

