# ---------------------------------------------------------------- the crab (a game bone)
CR = ["# A little red crab that scuttles along the sand: a squat body, two claws, six legs, stalk eyes.",
      "# Faces -Y; origin on the sand under its body.",
      "new",
      f"material new Shell {col('red')} --no-slot",
      f"material new Eye {col('white')} --no-slot",
      "add mesh uv-sphere --name Body --segments 8 --rings 4 --radius 1 --location 0 0 0",
      "scale 0.32 0.22 0.15", "apply --scale", "set location 0 0 0.2", "apply --location",
      "material assign Shell"]
for s, x in (("L", -1), ("R", 1)):
    CR += [f"add mesh ico-sphere --name Claw{s} --subdivisions 1 --radius 0.12 --location {x * 0.38} -0.22 0.22",
           "material assign Shell",
           f"add mesh cylinder --name Stalk{s} --vertices 4 --radius 0.03 --depth 0.16 --location {x * 0.1} -0.12 0.36",
           "material assign Shell",
           f"add mesh ico-sphere --name Eye{s} --subdivisions 1 --radius 0.06 --location {x * 0.1} -0.13 0.45",
           "material assign Eye"]
    for k, y in enumerate((-0.08, 0.04, 0.16)):
        CR += [f"add mesh cube --name Leg{s}{k} --size 1 --location {x * 0.38} {y} 0.08",
               "scale 0.22 0.05 0.05", "apply --scale", f"set rotation 0 {x * -30} 0", "material assign Shell"]
CR += ["select all", "shade flat", "export crab.glb"]
write("crab", CR)

