    "add mesh cube --name A --size 1 --location 0 0 0", "scale 0.36 0.08 0.1", "apply --scale",
    "add mesh cube --name B --size 1 --location 0 0 0", "scale 0.1 0.08 0.36", "apply --scale",
    "select A B", "active A", "join",
